  import React, { useEffect, useState } from 'react';
  import { Search, RotateCcw, Printer, FileText } from 'lucide-react';
  import { getTransfers, getTransfer } from '../services/api';
  const safe = (res) =>
    res?.data?.data?.data || 
    res?.data?.data || 
    res?.data || 
    [];

  const PrintBon = ({ transfer, onClose }) => {
    if (!transfer) return null;
    const openBon = async (id) => {
  try {
    const res = await getTransfer(id);

    const data =
      res?.data?.data ||
      res?.data ||
      null;

    setSelectedTransfer(data);

  } catch (err) {
    console.error(err);
  }
};
    return (
      <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50">
        <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg p-8 print:shadow-none print:rounded-none">
          <div className="text-center mb-6 border-b pb-4">
            <div className="w-12 h-12 bg-green-800 rounded-xl flex items-center justify-center mx-auto mb-2">
              <span className="text-white font-bold text-sm">OCP</span>
            </div>
            <h2 className="font-display font-bold text-xl text-gray-900">Bon de Décharge</h2>
            <p className="text-gray-500 text-sm">Transfert #{transfer.id}</p>
          </div>
          <div className="space-y-3 text-sm">
            {[
              ['Produit', transfer.product_name], ['Catégorie', transfer.category],
              ['Quantité transférée', `${transfer.quantity}`],
              ['Destination', transfer.destination], ['Personne', transfer.person_name],
              ['Effectué par', transfer.transferred_by], ['Date', transfer.created_at],
              ['Notes', transfer.notes],
            ].filter(([,v]) => v).map(([l,v]) => (
              <div key={l} className="flex justify-between border-b border-gray-100 pb-2">
                <span className="text-gray-500 font-medium">{l}</span>
                <span className="font-semibold text-gray-800">{v}</span>
              </div>
            ))}
          </div>
          <div className="flex justify-end gap-3 mt-6 pt-4 border-t no-print">
            <button onClick={onClose} className="btn-secondary">Fermer</button>
            <button onClick={() => window.print()} className="btn-primary"><Printer size={16} /> Imprimer</button>
          </div>
        </div>
      </div>
    );
  };

  export default function TransfersHistoryPage() {
    const openBon = async (id) => {
  try {
    const res = await getTransfer(id);

    const data =
      res?.data?.data ||
      res?.data ||
      null;

    setSelectedTransfer(data);

  } catch (err) {
    console.error("ERROR OPEN BON:", err);
  }
};
    const [transfers, setTransfers] = useState([]);
    const [filters, setFilters] = useState({ search: '', date: '' });
    const [loading, setLoading] = useState(true);
    const [selectedTransfer, setSelectedTransfer] = useState(null);

  const load = async () => {
    try {
      const res = await getTransfers();

  const data =
    res?.data?.data?.data || // pagination
    res?.data?.data ||       // resource
    res?.data ||             // direct
    [];

  console.log("TRANSFERS ARRAY:", data); // 👈 دابا خاصها تكون array

  setTransfers(Array.isArray(data) ? data : []);

    } catch (err) {
      console.error(err);
      setTransfers([]);
    }
  };

  useEffect(() => {
    const load = async () => {
      try {
        const res = await getTransfers();

        const data =
          res?.data?.data?.data ||
          res?.data?.data ||
          res?.data ||
          [];

        console.log("TRANSFERS ARRAY:", data);

        setTransfers(Array.isArray(data) ? data : []);
      } catch (err) {
        console.error(err);
        setTransfers([]);
      } finally {
        setLoading(false); // 👈 مهم بزاف
      }
    };

    load();
  }, []);
    const reset = () => setFilters({ search: '', date: '' });

    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="font-display text-2xl font-bold text-gray-900">Historique des Transferts</h1>
            <p className="text-gray-500 text-sm">Suivi de tous les mouvements d'articles</p>
          </div>
          <button onClick={() => window.print()} className="bg-amber-500 hover:bg-amber-600 text-white px-4 py-2 rounded-xl text-sm font-semibold flex items-center gap-2">
            <Printer size={16} /> Imprimer
          </button>
        </div>

        {selectedTransfer && <PrintBon transfer={selectedTransfer} onClose={() => setSelectedTransfer(null)} />}

        {/* Filters */}
        <div className="card">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="md:col-span-2">
              <label className="label">Recherche par nom</label>
              <div className="relative">
                <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <input placeholder="Nom du produit ou personne..." value={filters.search}
                  onChange={e => setFilters({...filters, search: e.target.value})} className="input-field pl-9" />
              </div>
            </div>
            <div>
              <label className="label">Date</label>
              <input type="date" value={filters.date}
                onChange={e => setFilters({...filters, date: e.target.value})} className="input-field" />
            </div>
          </div>
          <div className="flex justify-end mt-4">
            <button onClick={reset} className="btn-secondary gap-1.5"><RotateCcw size={15} /> Réinitialiser</button>
          </div>
        </div>

        <div className="card overflow-x-auto">
          {loading ? (
            <div className="flex justify-center py-12"><div className="animate-spin w-8 h-8 border-4 border-green-600 border-t-transparent rounded-full" /></div>
          ) : (
            <table className="w-full text-sm">
              <thead><tr className="border-b text-xs text-gray-400 uppercase tracking-wide">
                {['Produit','Description','Quantité','Destination','Personne','Effectué par','Notes','Actions'].map(h =>
                  <th key={h} className="pb-3 text-left pr-4">{h}</th>)}
              </tr></thead>
              <tbody className="divide-y divide-gray-50">
              {Array.isArray(transfers) && transfers.map(t => (
                  <tr key={t.id} className="hover:bg-gray-50">
                    <td className="py-3 pr-4 font-semibold text-gray-800">{t.product_name}<br/><span className="text-xs text-gray-400 font-normal">{t.category}</span></td>
                    <td className="py-3 pr-4 text-gray-600 text-xs">{t.description}</td>
                    <td className="py-3 pr-4 font-bold text-green-700">{t.quantity}</td>
                    <td className="py-3 pr-4 text-gray-600">{t.destination}</td>
                    <td className="py-3 pr-4 text-gray-600">{t.person_name}</td>

                    <td className="py-3 pr-4 text-gray-400 text-xs max-w-xs truncate">{t.notes}</td>
                    <td className="py-3">
                      <button onClick={() => openBon(t.id)} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-green-50 text-green-700 transition-colors" title="Bon de décharge">
                        <FileText size={15} />
                      </button>
                    </td>
                  </tr>
                ))}
                {transfers.length === 0 && (
                  <tr><td colSpan={8} className="text-center py-12 text-gray-400">Aucun transfert trouvé</td></tr>
                )}
              </tbody>
            </table>
          )}
        </div>
      </div>
    );
  }
